js:
d = [];
JSON.parse(getResCode()).data.list.map(_ => {
    d.push({
        title: _.title,
        desc: _.currrentDesc,
        img: _.img,
        url: "http://wapi.kuwo.cn/openapi/v1/shortplay/videoList?albumId=" + _.url + $("").rule(() => {
            d = [];
            JSON.parse(getResCode()).data.list.map(_ => {
                t = _.duration;
                s = t % 60;
                m = (t - s) / 60;
                desc = '🔥 ' + _.listencnt + '\n📼 0' + m + ':' + s;
                d.push({
                    title: _.name,
                    desc: desc,
                    img: _.img,
                    url: "http://nmobi.kuwo.cn/mobi.s?f=web&type=get_url_by_vid&vid=" + _.mvpayinfo.vid + $("").lazyRule(() => {
                        res = String(fetch(input));
                        return res.split('url=')[1].split(/\s*\n/)[0];
                    }),
                    col_type: 'movie_1_vertical_pic'
                });
            });
            setResult(d);
        })
    });
});
setResult(d);
